def caesar_cipher(text: str, shift: int) -> str:
    result = []
    for char in text:
        if char.isupper():
            shifted = (ord(char) - ord('A') + shift) % 26
            result.append(chr(shifted + ord('A')))
        elif char.islower():
            shifted = (ord(char) - ord('a') + shift) % 26
            result.append(chr(shifted + ord('a')))
        else:
            result.append(char)
    return ''.join(result)

